-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        portiq_fund_id,
        fund_name,
        gp_name,
        gp_lei,
        fund_lei,
        shared_external_id,
        asset_class,
        strategy,
        vintage_year,
        currency,
        violation_00,
        violation_01,
        violation_02
    from {{ ref("investment__portiq_fund_extract__checked") }}
),
violations as (
    select
        'portiq_fund_id_not_null' as rule_name,
        portiq_fund_id,
        fund_name,
        gp_name,
        gp_lei,
        fund_lei,
        shared_external_id,
        asset_class,
        strategy,
        vintage_year,
        currency
    from quarantined
    where violation_00

    union all

    select
        'portiq_fund_id_unique' as rule_name,
        portiq_fund_id,
        fund_name,
        gp_name,
        gp_lei,
        fund_lei,
        shared_external_id,
        asset_class,
        strategy,
        vintage_year,
        currency
    from quarantined
    where violation_01

    union all

    select
        'fund_name_not_null' as rule_name,
        portiq_fund_id,
        fund_name,
        gp_name,
        gp_lei,
        fund_lei,
        shared_external_id,
        asset_class,
        strategy,
        vintage_year,
        currency
    from quarantined
    where violation_02
)

select
    rule_name,
    portiq_fund_id,
    fund_name,
    gp_name,
    gp_lei,
    fund_lei,
    shared_external_id,
    asset_class,
    strategy,
    vintage_year,
    currency
from violations
